          "model_answer": "Without wheels, horses, or metal cranes, Neolithic engineers raised Stonehenge through clever teamwork. First, teams hauled spotted bluestones 140 miles from the Preseli Hills in Wales using sledges, rafts, and twisted plant ropes. Next, hundreds of workers dragged 25-tonne grey sarsen boulders twenty miles across Wiltshire over wooden log rollers. After tipping tall uprights into deep pits, builders levered heavy capstones up timber platforms and locked each giant trilithon tight with stone peg-and-hole mortise-and-tenon joints!"
