        "items": [
          {
            "stage": 1,
            "question": "What stone-built New Stone Age village in Orkney was uncovered by a fierce storm in 1850 with stone beds and dressers still inside?",
            "answer": "Skara Brae",
            "explanation": "Built around 3100 BC in treeless Orkney, Skara Brae's flagstone houses and furniture survived beneath coastal sand dunes."
          },
          {
            "stage": 1,
            "question": "What do archaeologists call the giant horseshoe pairs of upright sarsen stones topped by horizontal lintels at Stonehenge?",
            "answer": "Trilithons (meaning \"three stones\")",
            "explanation": "Each giant sarsen trilithon locked its top lintel stone firmly onto two uprights using carved mortise-and-tenon joints."
          },
          {
            "stage": 2,
            "question": "What does \"smelting\" mean, and which two metals were mixed (nine parts to one part) to make bronze?",
            "answer": "Melting liquid metal out of rock in a hot fire; nine parts copper and one part tin",
            "explanation": "Bronze Age smiths smelted Welsh copper and Cornish tin before casting bronze tools in two-piece moulds."
          },
          {
            "stage": 3,
            "question": "Why did wooden axe handles, plant-fibre cloth, porridge, and Britain's oldest wheel survive at Must Farm (c. 900 BC)?",
            "answer": "Burning stilt roundhouses fell straight into thick, airless wet river mud so nothing rotted away",
            "explanation": "Waterlogged Cambridgeshire river silt sealed Must Farm like a time capsule, earning it the nickname \"Britain's Pompeii.\""
          },
          {
            "stage": 3,
            "question": "How did Bronze Age builders fasten the thick oak planks of the Dover Boat to cross the English Channel?",
            "answer": "They stitched the oak planks together using twisted yew branches and sealed seams with moss",
            "explanation": "Unearthed in Kent in 1992, the sewn-plank Dover Boat carried Bronze Age crews and trade cargoes between Britain and France."
          }
        ],
        "current_items": [
          {
            "stage": 1,
            "question": "Why could Iron Age blacksmiths make far more tools from iron after 800 BC than earlier smiths could make from bronze?",
            "answer": "Reddish iron ore rock was common across Britain, whereas tin and copper were rare",
            "explanation": "Widespread iron ore meant local village blacksmiths could hammer tough ploughshares, saws, and sickles for everyday farmers."
          },
          {
            "stage": 1,
            "question": "What was an Iron Age \"rotary quern\", and how did it work?",
            "answer": "A round stone hand-mill spun with a wooden handle to grind grain into flour",
            "explanation": "Spinning two round millstones ground wheat and barley far faster than rubbing flat saddle stones back and forth."
          },
          {
            "stage": 2,
            "question": "How did Celtic families build the walls of their cone-roofed thatched roundhouses?",
            "answer": "Wattle and daub (woven hazel sticks plastered thickly with mud, clay, and straw)",
            "explanation": "Wattle-and-daub walls kept heat inside while hearth smoke filtered gently through the thatched roof without a chimney."
          },
          {
            "stage": 2,
            "question": "Name the giant multi-ringed Iron Age hillfort in Dorset and the famous chalk hill figure in Oxfordshire.",
            "answer": "Maiden Castle in Dorset and the Uffington White Horse in Oxfordshire",
            "explanation": "Maiden Castle's huge chalk ramparts protected hundreds of villagers, while tribes scoured gleaming white chalk into the Uffington Horse."
          },
          {
            "stage": 3,
            "question": "What were twisted gold \"torcs\" and stamped gold \"staters\", and what ended British prehistory in AD 43?",
            "answer": "Heavy twisted gold neck rings and Celtic gold coins; Emperor Claudius's Roman invasion in AD 43",
            "explanation": "Treasures like the Snettisham Great Torc and gold staters flourished right before Roman legions brought written rule in AD 43."
          }
        ]
